// Ejemplo completo: módulo de validación
// validaciones.js
export const REGLAS = {
  EMAIL: /^[^\s@]+@[^\s@]+\.[^\s@]+$/,
  TELEFONO: /^\d{10}$/,
};

export function validarEmail(email) {
  return REGLAS.EMAIL.test(email);
}

export function validarTelefono(tel) {
  return REGLAS.TELEFONO.test(String(tel));
}

export default function validar(campo, valor) {
  switch (campo) {
    case 'email': return validarEmail(valor);
    case 'telefono': return validarTelefono(valor);
    default: return valor !== null && valor !== undefined && valor !== '';
  }
}

// main.js
import validar, { validarEmail, REGLAS } from './validaciones.js';
console.log(validar('email', 'test@ejemplo.com')); // true
console.log(validarEmail('no-email'));              // false

// Namespace import — importar todo como objeto
import * as Math2 from './matematicas.js';
// Equivale a:
// const Math2 = { sumar, restar, PI, ... };

console.log(Math2.sumar(1, 2));   // 3
console.log(Math2.PI);            // 3.14...

// Útil cuando no sabes qué necesitas aún
// o cuando hay muchos exports y quieres agruparlos
// bajo un namespace semántico

// Con alias para evitar colisión con el Math nativo:
import * as MatUtils from './mat-utils.js';
console.log(MatUtils.factorial(5));

