// Simula el contenido de geometria.js
const PI = Math.PI;

function areaCirculo(radio) {
  return PI * radio ** 2;
}

function perimetroCirculo(radio) {
  return 2 * PI * radio;
}

function areaRectangulo(base, altura) {
  return base * altura;
}

// El 'módulo exportado'
const geometria = { PI, areaCirculo, perimetroCirculo, areaRectangulo };

// Uso del módulo
const ac = +geometria.areaCirculo(5).toFixed(2);
const pr = +geometria.perimetroCirculo(5).toFixed(2);

console.log(ac, pr); // 78.54, 31.42

// Simula el módulo conversor.js
const UNIDADES = ['km', 'm', 'cm'];

function convertir(valor, de, a) {
  if (de === a) return valor;

  const aMetros = { km: 1000, m: 1, cm: 0.01 };
  const valorEnMetros = valor * aMetros[de];
  return valorEnMetros / aMetros[a];
}

// default export → la función principal
const conversorDefault = convertir;
// named exports → objeto con las exportaciones nombradas
const conversorNamed = { UNIDADES };

const r1 = conversorDefault(5, 'km', 'm');
const r2 = conversorDefault(200, 'cm', 'km');
const tieneUnidades = 'UNIDADES' in conversorNamed;

console.log(r1, r2, tieneUnidades);

function moneda(valor, simbolo = '$') {
  return simbolo + valor.toLocaleString('es-CO');
}

function porcentaje(valor, decimales = 1) {
  return valor.toFixed(decimales) + '%';
}

function fecha(isoString) {
  const [anio, mes, dia] = isoString.split('-');
  return `${dia}/${mes}/${anio}`;
}

function formatear(tipo, valor, opciones = {}) {
  if (tipo === 'moneda') return moneda(valor, opciones.simbolo);
  if (tipo === 'porcentaje') return porcentaje(valor, opciones.decimales);
  if (tipo === 'fecha') return fecha(valor);
}

// El objeto 'módulo'
const Formato = { moneda, porcentaje, fecha, formatear };

const fm = Formato.moneda(1234567);
const fp = Formato.porcentaje(85.5);
const ff = Formato.fecha('2026-05-01');
const fd = Formato.formatear('moneda', 50000, { simbolo: '€' });

console.log(fm, fp, ff, fd);
